import path from 'node:path';
import { NPM_AUDIT_FILE } from '../constants.js';
import { runNpmAuditJson } from '../npmSecurityAudit.js';
const auditCache = new Map();
export function resetAuditCache() {
    auditCache.clear();
}
const securityAuditPlugin = (options) => {
    const { logger, auditRoot, extensionLabel } = options;
    return {
        name: 'ui-extensions-security-audit-plugin',
        async generateBundle() {
            const resolvedRoot = path.resolve(auditRoot);
            if (auditCache.has(resolvedRoot)) {
                logger.debug(`[${extensionLabel}] npm audit already ran for ${resolvedRoot}, skipping`);
                return;
            }
            const auditPromise = runNpmAuditJson(resolvedRoot);
            auditCache.set(resolvedRoot, auditPromise);
            const result = await auditPromise;
            if (result.skipped) {
                logger.debug(`[${extensionLabel}] Skipping npm audit: package.json or package-lock.json not found in ${auditRoot}`);
                return;
            }
            if (result.exitCode === 0) {
                logger.info(`[${extensionLabel}] npm audit report clean for ${resolvedRoot}`);
            }
            else {
                let isSyntheticError = false;
                try {
                    const parsed = JSON.parse(result.source);
                    isSyntheticError = parsed != null && 'error' in parsed;
                }
                catch {
                    isSyntheticError = true;
                }
                if (isSyntheticError) {
                    logger.error(`[${extensionLabel}] npm audit failed for ${resolvedRoot} (exit code ${result.exitCode})`);
                }
                else {
                    logger.warn(`[${extensionLabel}] npm audit found vulnerabilities in ${resolvedRoot} (exit code ${result.exitCode})`);
                }
            }
            const folderName = path.basename(resolvedRoot);
            this.emitFile({
                type: 'asset',
                fileName: path.normalize(`${folderName}-${NPM_AUDIT_FILE}`),
                source: result.source,
            });
        },
    };
};
export default securityAuditPlugin;
